package co.nz.restorelab;

import org.geoserver.catalog.*;
import org.geoserver.wps.gs.GeoServerProcess;
import org.geotools.api.data.*;
import org.geotools.api.feature.simple.SimpleFeature;
import org.geotools.api.feature.simple.SimpleFeatureType;
import org.geotools.api.filter.Filter;
import org.geotools.api.filter.FilterFactory;
import org.geotools.api.filter.expression.Expression;
import org.geotools.api.referencing.FactoryException;
import org.geotools.api.referencing.crs.CoordinateReferenceSystem;
import org.geotools.api.referencing.operation.NoninvertibleTransformException;
import org.geotools.api.referencing.operation.TransformException;
import org.geotools.api.util.ProgressListener;
import org.geotools.data.DefaultTransaction;
import org.geotools.data.simple.SimpleFeatureCollection;
import org.geotools.data.simple.SimpleFeatureIterator;
import org.geotools.factory.CommonFactoryFinder;
import org.geotools.feature.DefaultFeatureCollection;
import org.geotools.feature.simple.SimpleFeatureBuilder;
import org.geotools.geometry.jts.ReferencedEnvelope;
import org.geotools.process.ProcessException;
import org.geotools.process.factory.DescribeParameter;
import org.geotools.process.factory.DescribeProcess;
import org.geotools.process.factory.DescribeResult;
import org.geotools.referencing.CRS;

import java.io.IOException;
import java.util.Calendar;
import java.util.Date;
import java.util.List;

@DescribeProcess(
        title = "CalculateYearlyMean",
        description = "Calculates the yearly mean for a given year"
)
public class CalculateYearlyMean implements GeoServerProcess {
    Catalog catalog;
    CalculateYearlyMean(Catalog catalog) {
        this.catalog = catalog;
    }

    @DescribeResult(name = "result", description = "Returns the layer name that was created")
    public String execute(
            @DescribeParameter(name = "year", description = "Year to calculate") int year,
            ProgressListener listener
    ) throws ProcessException {
        LayerInfo layerInfo = catalog.getLayerByName("restore-lab:smc_measurements");

        if (layerInfo == null) {
            throw new ProcessException("Layer not found");
        }

        FeatureTypeInfo featureTypeInfo = (FeatureTypeInfo) layerInfo.getResource();
        SimpleFeatureSource featureSource;
        try {
            featureSource = (SimpleFeatureSource) featureTypeInfo.getFeatureSource(null, null);
        } catch (IOException e) {
            throw new ProcessException("Error getting feature source", e);
        }
        Calendar calendar = Calendar.getInstance();
        // Get the start date
        calendar.set(Calendar.YEAR, year);
        calendar.set(Calendar.DAY_OF_MONTH, 0);
        calendar.set(Calendar.HOUR, 0);
        calendar.set(Calendar.MINUTE, 0);
        calendar.set(Calendar.SECOND, 0);
        Date startDate = calendar.getTime();

        // Get the end date
        calendar.set(Calendar.MONTH, 11);
        calendar.set(Calendar.DAY_OF_MONTH, 31);
        calendar.set(Calendar.HOUR, 23);
        calendar.set(Calendar.MINUTE, 59);
        calendar.set(Calendar.SECOND, 59);
        Date endDate = calendar.getTime();

        FilterFactory filterFactory = CommonFactoryFinder.getFilterFactory();
        Expression timeAttr = filterFactory.property("utc_time");
        Filter timeFilter = filterFactory.between(timeAttr, filterFactory.literal(startDate), filterFactory.literal(endDate));

        SimpleFeatureCollection range;
        try {
            range = featureSource.getFeatures(timeFilter);
        } catch (IOException e) {
            throw new ProcessException("Error getting features", e);
        }

        GridCalculator gridCalculator;
        try {
            gridCalculator = new GridCalculator(800);
        } catch (NoninvertibleTransformException e) {
            throw new ProcessException("Error decoding source or target CRS", e);
        } catch (FactoryException e) {
            throw new ProcessException("Error creating inverse crs transformer", e);
        }

        List<GridCell> grid = gridCalculator.aggregate(range, listener);
        WorkspaceInfo ws = catalog.getWorkspaceByName("restore-lab");
        DataStoreInfo storeInfo = catalog.getDefaultDataStore(ws);
        DataAccess<?, ?> dataAccess;
        try {
            dataAccess = storeInfo.getDataStore(null);
        } catch (IOException e) {
            throw new ProcessException("Error getting data store", e);
        }

        SimpleFeatureType featureType;

        DataStore dataStore = (DataStore) dataAccess;

        String typeName = "yearly_mean_smc_" + year;
        try {
            featureType = gridCalculator.getResultFeatureType("EPSG:3857", typeName);
        } catch (FactoryException e) {
            throw new ProcessException("");
        }

        // Make the simple feature collection
        DefaultFeatureCollection collection = new DefaultFeatureCollection();
        SimpleFeatureBuilder builder = new SimpleFeatureBuilder(featureType);
        int fid = 0;

        for (GridCell cell : grid) {
            builder.add(cell.getPolygon());
            builder.add(cell.average());
            SimpleFeature feature = builder.buildFeature("fid-"+fid++);
            collection.add(feature);
            float progress = 0.33f + 0.33f * (float) fid / grid.size();
            listener.progress(progress);
        }

        fid = 0;
        try {
            dataStore.createSchema(featureType);
            Transaction transaction = new DefaultTransaction("create");

            try (FeatureWriter<SimpleFeatureType, SimpleFeature> writer = dataStore.getFeatureWriterAppend(typeName, transaction)) {
                try (SimpleFeatureIterator features = collection.features()) {
                   while (features.hasNext()) {
                       SimpleFeature feature = features.next();
                       SimpleFeature newFeature = writer.next();
                       newFeature.setAttributes(feature.getAttributes());
                       writer.write();

                       float progress = 0.66f + 0.33f * (float) fid / grid.size();
                       listener.progress(progress);
                   }
                }
            }
            transaction.commit();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }

        FeatureTypeInfo ftiNew = catalog.getFactory().createFeatureType();
        ftiNew.setName(typeName);
        ftiNew.setNativeName(typeName);
        ftiNew.setStore(storeInfo);
        ftiNew.setEnabled(true);
        ftiNew.getMetadata().put("srsHandling", "FORCE_DECLARED");
        ftiNew.setNamespace(catalog.getNamespaceByPrefix("restore-lab"));
        ftiNew.setSRS("EPSG:3857");
        ftiNew.setNativeBoundingBox(collection.getBounds());
        try {
            CoordinateReferenceSystem crs = CRS.decode("EPSG:3857");
            ftiNew.setNativeCRS(crs);
            ReferencedEnvelope latLonBounds = collection.getBounds().transform(crs, true);
            ftiNew.setLatLonBoundingBox(latLonBounds);
        } catch (FactoryException | TransformException e) {
            throw new ProcessException("Error decoding EPSG to set native");
        }

        catalog.add(ftiNew);

        LayerInfo newLayer = catalog.getFactory().createLayer();
        newLayer.setResource(ftiNew);
        newLayer.setEnabled(true);
        newLayer.setName(typeName);
        newLayer.setDefaultStyle(catalog.getStyleByName("Soil Moisture"));

        catalog.add(newLayer);

        listener.complete();

        return "Layer created: restore-lab:" + typeName;
    }
}

package co.nz.restorelab;

import org.geoserver.catalog.*;
import org.geoserver.wps.gs.GeoServerProcess;
import org.geotools.api.data.*;
import org.geotools.api.feature.simple.SimpleFeature;
import org.geotools.api.feature.simple.SimpleFeatureType;
import org.geotools.api.filter.Filter;
import org.geotools.api.filter.FilterFactory;
import org.geotools.api.filter.expression.Expression;
import org.geotools.api.referencing.FactoryException;
import org.geotools.api.referencing.crs.CoordinateReferenceSystem;
import org.geotools.api.referencing.operation.NoninvertibleTransformException;
import org.geotools.api.referencing.operation.TransformException;
import org.geotools.api.util.ProgressListener;
import org.geotools.data.DefaultTransaction;
import org.geotools.data.simple.SimpleFeatureCollection;
import org.geotools.data.simple.SimpleFeatureIterator;
import org.geotools.factory.CommonFactoryFinder;
import org.geotools.feature.DefaultFeatureCollection;
import org.geotools.feature.simple.SimpleFeatureBuilder;
import org.geotools.geometry.jts.ReferencedEnvelope;
import org.geotools.process.ProcessException;
import org.geotools.process.factory.DescribeParameter;
import org.geotools.process.factory.DescribeProcess;
import org.geotools.process.factory.DescribeResult;
import org.geotools.referencing.CRS;

import java.io.IOException;
import java.util.Calendar;
import java.util.Date;
import java.util.List;

@DescribeProcess(
        title = "CalculateRollingMean",
        description = "Calculates the rolling mean for each month in a given year"
)
public class CalculateYearlyMean implements GeoServerProcess {
    Catalog catalog;
    CalculateYearlyMean(Catalog catalog) {
        this.catalog = catalog;
    }

    @DescribeResult(name = "result", description = "Returns the layer name that was created")
    public String execute(
            @DescribeParameter(name = "year", description = "Year to calculate") int year,
            @DescribeParameter(name = "rollingMonths", description = "Number of months for rolling window", defaultValue = "12") int rollingMonths,
            ProgressListener listener
    ) throws ProcessException {
        LayerInfo layerInfo = catalog.getLayerByName("restore-lab:smc_measurements");
        if (layerInfo == null) {
            throw new ProcessException("Layer not found");
        }

        FeatureTypeInfo featureTypeInfo = (FeatureTypeInfo) layerInfo.getResource();
        SimpleFeatureSource featureSource;
        try {
            featureSource = (SimpleFeatureSource) featureTypeInfo.getFeatureSource(null, null);
        } catch (IOException e) {
            throw new ProcessException("Error getting feature source", e);
        }

        // Create feature type with temporal attributes
        String typeName = "rolling_mean_smc_" + year;
        SimpleFeatureType featureType;
        try {
            SimpleFeatureTypeBuilder builder = new SimpleFeatureTypeBuilder();
            builder.setName(typeName);
            builder.setCRS(CRS.decode("EPSG:3857"));
            builder.add("geometry", Polygon.class);
            builder.add("smc_mat", Double.class);
            builder.add("measurement_date", Date.class);
            featureType = builder.buildFeatureType();
        } catch (FactoryException e) {
            throw new ProcessException("Error creating feature type", e);
        }

        // Process each month of the year
        DefaultFeatureCollection collection = new DefaultFeatureCollection();
        Calendar calendar = Calendar.getInstance();
        GridCalculator gridCalculator;
        try {
            gridCalculator = new GridCalculator(5000);
        } catch (Exception e) {
            throw new ProcessException("Error creating grid calculator", e);
        }

        FilterFactory filterFactory = CommonFactoryFinder.getFilterFactory();
        Expression timeAttr = filterFactory.property("utc_time");

        for (int month = 0; month < 12; month++) {
            // Set target month end date
            calendar.set(year, month, 1);
            calendar.set(Calendar.DAY_OF_MONTH, calendar.getActualMaximum(Calendar.DAY_OF_MONTH));
            Date endDate = calendar.getTime();

            // Set rolling window start date
            calendar.add(Calendar.MONTH, -rollingMonths);
            Date startDate = calendar.getTime();

            // Create time filter
            Filter timeFilter = filterFactory.between(timeAttr, 
                filterFactory.literal(startDate), 
                filterFactory.literal(endDate));

            // Get features for this period
            SimpleFeatureCollection range;
            try {
                range = featureSource.getFeatures(timeFilter);
            } catch (IOException e) {
                throw new ProcessException("Error getting features", e);
            }

            // Calculate grid for this period
            List<GridCell> grid = gridCalculator.aggregate(range, listener);

            // Create features
            SimpleFeatureBuilder builder = new SimpleFeatureBuilder(featureType);
            for (GridCell cell : grid) {
                builder.add(cell.getPolygon());
                builder.add(cell.average());
                builder.add(endDate);  // Use end of month as measurement date
                collection.add(builder.buildFeature(null));
            }

            listener.progress(0.5f * (float) month / 12);
        }

        // Create the layer
        WorkspaceInfo ws = catalog.getWorkspaceByName("restore-lab");
        DataStoreInfo storeInfo = catalog.getDefaultDataStore(ws);
        DataStore dataStore;
        try {
            dataStore = (DataStore) storeInfo.getDataStore(null);
            dataStore.createSchema(featureType);

            // Write features
            try (Transaction transaction = new DefaultTransaction("create")) {
                try (FeatureWriter<SimpleFeatureType, SimpleFeature> writer = 
                        dataStore.getFeatureWriterAppend(typeName, transaction)) {
                    try (SimpleFeatureIterator features = collection.features()) {
                        while (features.hasNext()) {
                            SimpleFeature feature = features.next();
                            SimpleFeature newFeature = writer.next();
                            newFeature.setAttributes(feature.getAttributes());
                            writer.write();
                        }
                    }
                    transaction.commit();
                }
            }
        } catch (IOException e) {
            throw new ProcessException("Error writing features", e);
        }

        // Create and configure the feature type info
        FeatureTypeInfo ftiNew = catalog.getFactory().createFeatureType();
        ftiNew.setName(typeName);
        ftiNew.setNativeName(typeName);
        ftiNew.setStore(storeInfo);
        ftiNew.setEnabled(true);
        ftiNew.getMetadata().put("srsHandling", "FORCE_DECLARED");
        ftiNew.setNamespace(catalog.getNamespaceByPrefix("restore-lab"));
        ftiNew.setSRS("EPSG:3857");
        ftiNew.setNativeBoundingBox(collection.getBounds());

        // Enable temporal aspects
        ftiNew.getMetadata().put("time", new DimensionInfo() {
            public boolean isEnabled() { return true; }
            public String getAttribute() { return "measurement_date"; }
            public DimensionPresentation getPresentation() { return DimensionPresentation.LIST; }
            public String getUnits() { return "ISO8601"; }
            public String getUnitSymbol() { return ""; }
            public String getStrategy() { return "LIST"; }
            public String getResolution() { return null; }
            public boolean isNearestMatchEnabled() { return false; }
            public String getReferenceValue() { return ""; }
        });

        try {
            CoordinateReferenceSystem crs = CRS.decode("EPSG:3857");
            ftiNew.setNativeCRS(crs);
            ReferencedEnvelope latLonBounds = collection.getBounds().transform(crs, true);
            ftiNew.setLatLonBoundingBox(latLonBounds);
        } catch (Exception e) {
            throw new ProcessException("Error setting CRS", e);
        }

        catalog.add(ftiNew);

        // Create and configure the layer
        LayerInfo newLayer = catalog.getFactory().createLayer();
        newLayer.setResource(ftiNew);
        newLayer.setEnabled(true);
        newLayer.setName(typeName);
        newLayer.setDefaultStyle(catalog.getStyleByName("Soil Moisture"));

        catalog.add(newLayer);
        listener.complete();

        return "Layer created: restore-lab:" + typeName;
    }
}

package co.nz.restorelab;

import org.geoserver.catalog.Catalog;
import org.geoserver.catalog.FeatureTypeInfo;
import org.geoserver.catalog.LayerInfo;
import org.geoserver.wps.gs.GeoServerProcess;
import org.geotools.api.data.SimpleFeatureSource;
import org.geotools.api.feature.simple.SimpleFeature;
import org.geotools.api.feature.simple.SimpleFeatureType;
import org.geotools.api.filter.Filter;
import org.geotools.api.filter.FilterFactory;
import org.geotools.api.filter.expression.Expression;
import org.geotools.api.referencing.FactoryException;
import org.geotools.api.referencing.operation.NoninvertibleTransformException;
import org.geotools.api.util.ProgressListener;
import org.geotools.data.collection.ListFeatureCollection;
import org.geotools.data.simple.SimpleFeatureCollection;
import org.geotools.data.simple.SimpleFeatureIterator;
import org.geotools.factory.CommonFactoryFinder;
import org.geotools.feature.simple.SimpleFeatureBuilder;
import org.geotools.geometry.jts.ReferencedEnvelope;
import org.geotools.process.ProcessException;
import org.geotools.process.factory.DescribeParameter;
import org.geotools.process.factory.DescribeProcess;
import org.geotools.process.factory.DescribeResult;
import org.locationtech.jts.geom.Geometry;

import java.io.IOException;
import java.text.SimpleDateFormat;
import java.util.*;

@DescribeProcess(title = "temporalGridChange", description = "Computes the gridded change between two date ranges for the soil moisture dataset.")
public class TemporalGridChange implements GeoServerProcess {
    Catalog catalog;

    TemporalGridChange(Catalog catalog) {
        this.catalog = catalog;
    }
    @DescribeResult(description = "The gridded change between the two date ranges.")
    public SimpleFeatureCollection execute(
            @DescribeParameter(name = "startTime1", description = "Starting Date Time for time period 1") String startTime,
            @DescribeParameter(name = "endTime1", description = "Ending Date Time for time period 1") String endTime,
            @DescribeParameter(name = "year", description = "Year to compare the time range to.") int year,
            @DescribeParameter(name = "outputCRS", description = "Change the default CRS to output", defaultValue = "EPSG:3857") String crs,
            ProgressListener listener
    ) throws ProcessException {
        LayerInfo layerInfo = catalog.getLayerByName("restore-lab:smc_measurements");
        LayerInfo layerInfoPrev = catalog.getLayerByName("restore-lab:yearly_mean_smc_"+year);

        if (layerInfoPrev == null) {
            throw new ProcessException("We don't seem to have data for the year " + year);
        }

        if (layerInfo == null) {
            throw new ProcessException("Layer not found");
        }

        FeatureTypeInfo featureTypeInfo = (FeatureTypeInfo) layerInfo.getResource();
        FeatureTypeInfo featureTypeInfoPrev = (FeatureTypeInfo) layerInfoPrev.getResource();
        SimpleFeatureSource featureSource;
        SimpleFeatureSource featureSourcePrev;
        try {
            featureSource = (SimpleFeatureSource) featureTypeInfo.getFeatureSource(null, null);
            featureSourcePrev = (SimpleFeatureSource) featureTypeInfoPrev.getFeatureSource(null, null);
        } catch (IOException e) {
            throw new ProcessException("Error getting feature source", e);
        }

        // Convert the start and end times
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss");
        Date startDate, endDate;
        try {
            startDate = sdf.parse(startTime);
            endDate = sdf.parse(endTime);
        } catch (Exception e) {
            throw new ProcessException("Error parsing date", e);
        }

        if (startDate.after(endDate)) {
            throw new ProcessException("Start date is after end date for date range 1");
        }

        if (startDate.compareTo(endDate) == 0) {
            throw new ProcessException("Start date is equal to end date for date range 1");
        }

        Calendar calStart = Calendar.getInstance();
        Calendar calEnd = Calendar.getInstance();

        calStart.setTime(startDate);
        int startDay = calStart.get(Calendar.DAY_OF_YEAR);
        calEnd.setTime(endDate);
        int endDay = calEnd.get(Calendar.DAY_OF_YEAR);
        int gridSize;
        if (endDay-startDay > 7) {
            gridSize = 800;
            // Use mean for the month
            calStart.set(Calendar.DAY_OF_MONTH, calStart.getActualMinimum(Calendar.DAY_OF_MONTH));
            calEnd.set(Calendar.DAY_OF_MONTH, calEnd.getActualMaximum(Calendar.DAY_OF_MONTH));
        } else {
            gridSize = 2000;
            // Use week means
            calStart.set(Calendar.DAY_OF_WEEK, calStart.getFirstDayOfWeek());
            calEnd.set(Calendar.DAY_OF_WEEK, 8);
        }

        FilterFactory filterFactory = CommonFactoryFinder.getFilterFactory();
        Expression timeAttr = filterFactory.property("utc_time");
        Filter timeFilter1 = filterFactory.between(timeAttr, filterFactory.literal(startDate), filterFactory.literal(endDate));

        SimpleFeatureCollection range1;
        try {
            range1 = featureSource.getFeatures(timeFilter1);
        } catch (IOException e) {
            throw new ProcessException("Error getting features", e);
        }
        GridCalculator gridCalculator;
        try {
            gridCalculator = new GridCalculator(gridSize);
        } catch (FactoryException e) {
            throw new ProcessException("Error decoding source or target CRS", e);
        } catch (NoninvertibleTransformException e) {
            throw new ProcessException("Error creating inverse crs transformer", e);
        }

        List<GridCell> grid1 = gridCalculator.aggregate(range1, listener);

        // get the yearly mean
        ReferencedEnvelope bounds = range1.getBounds();

        Filter bboxFilter = filterFactory.bbox(
                "geometry",
                bounds.getMinX(),
                bounds.getMinY(),
                bounds.getMaxX(),
                bounds.getMaxY(),
                bounds.getCoordinateReferenceSystem().getIdentifiers().iterator().next().toString());

        SimpleFeatureCollection yearMean;
        try {
            yearMean = featureSource.getFeatures(bboxFilter);
        } catch (IOException e) {
            throw new ProcessException("Error getting features", e);
        }

        // Build lookup map from yearMean polygons to their GridCell value
        Map<Geometry, Double> yearMeanMap = new HashMap<>();
        try (SimpleFeatureIterator it = yearMean.features()) {
            while (it.hasNext()) {
                SimpleFeature f = it.next();
                Geometry poly = (Geometry) f.getAttribute("geometry");
                Double mean = (Double) f.getAttribute("smc_mat");
                yearMeanMap.put(poly, mean);
            }
        }

        List<SimpleFeature> results = new ArrayList<>();
        SimpleFeatureType resultType;
        try {
            resultType = gridCalculator.getResultFeatureType(crs, "gridcells");
        } catch (FactoryException e) {
            throw new ProcessException("Error decoding CRS value");
        }

        SimpleFeatureBuilder builder = new SimpleFeatureBuilder(resultType);
        int fid = 0;

        for (GridCell cell: grid1) {
            double val1 = cell.average();
            double val2 = 0;
            Double mean = yearMeanMap.get(cell.getPolygon());
            if (mean != null) {
                val2 = mean;
            }
            double change = val1 - val2;
            builder.add(cell.getPolygon());
            builder.add(change);
            results.add(builder.buildFeature(String.valueOf(fid++)));
        }

        return new ListFeatureCollection(resultType, results);
    }
}

package co.nz.restorelab;

import org.geoserver.catalog.Catalog;
import org.geoserver.catalog.FeatureTypeInfo;
